t.script:
                    let totalPrinted = 0;
                    let successCount = 0;
                    let errorCount = 0;
                    const templateId = ;

                    document.addEventListener('DOMContentLoaded', function() {
                        const barcodeInput = document.getElementById('barcode-input');

                        // Auto-focus on barcode input
                        barcodeInput.focus();

                        // Listen for barcode scanner (Enter key)
                        barcodeInput.addEventListener('keypress', function(e) {
                            if (e.key === 'Enter') {
                                e.preventDefault();
                                const barcode = this.value.trim();
                                if (barcode) {
                                    processBarcode(barcode);
                                    this.value = '';
                                }
                            }
                        });

                        // Ensure input always has focus
                        document.addEventListener('click', function() {
                            barcodeInput.focus();
                        });
                    });

                    function showStatus(type, message, productInfo = null) {
                        const statusArea = document.getElementById('status-area');
                        statusArea.className = 'status-area ' + type;

                        let html = '';
                        if (type === 'loading') {
                            html = '
';
                        }
                        html += '
' + message + '';

                        if (productInfo) {
                            html += `



${productInfo.sap_product_name || productInfo.product_name}


                                        الباركود:
                                        ${productInfo.barcode}
                                    `;
                            if (productInfo.sap_uom) {
                                html += `


                                        وحدة القياس (SAP):
                                        ${productInfo.sap_uom}
                                    `;
                            }
                            html += `


                                        اسم المنتج في Odoo:
                                        ${productInfo.product_name}


                            `;
                        }

                        statusArea.innerHTML = html;

                        // Auto-hide success messages
                        if (type === 'success') {
                            setTimeout(function() {
                                statusArea.style.display = 'none';
                                document.getElementById('barcode-input').focus();
                            }, 3000);
                        }
                    }

                    function updateStats() {
                        document.getElementById('total-printed').textContent = totalPrinted;
                        document.getElementById('success-count').textContent = successCount;
                        document.getElementById('error-count').textContent = errorCount;
                    }

                    async function processBarcode(barcode) {
                        try {
                            showStatus('loading', 'جاري البحث في SAP...');

                            // Lookup product from SAP
                            const response = await fetch('/sap/label/lookup', {
                                method: 'POST',
                                headers: {
                                    'Content-Type': 'application/json',
                                },
                                body: JSON.stringify({
                                    jsonrpc: '2.0',
                                    method: 'call',
                                    params: {
                                        barcode: barcode,
                                        template_id: templateId
                                    },
                                    id: new Date().getTime(),
                                }),
                            });

                            const data = await response.json();
                            const result = data.result;

                            if (result.success) {
                                showStatus('success', '✓ تم العثور على المنتج - جاري الطباعة...', result);

                                // Auto-print by opening print URL in hidden iframe
                                const printFrame = document.createElement('iframe');
                                printFrame.style.display = 'none';
                                printFrame.src = result.print_url;
                                document.body.appendChild(printFrame);

                                // Remove iframe after printing
                                setTimeout(() => {
                                    document.body.removeChild(printFrame);
                                }, 3000);

                                totalPrinted++;
                                successCount++;
                                updateStats();
                            } else {
                                showStatus('error', '✗ خطأ: ' + result.error);
                                errorCount++;
                                updateStats();

                                setTimeout(() => {
                                    document.getElementById('status-area').style.display = 'none';
                                    document.getElementById('barcode-input').focus();
                                }, 5000);
                            }
                        } catch (error) {
                            console.error('Error:', error);
                            showStatus('error', '✗ خطأ في الاتصال: ' + error.message);
                            errorCount++;
                            updateStats();
                        }
                    }
